Table:
  0.0.0.0/0          -> ISP-A     (default)
  10.0.0.0/8         -> core
  10.1.0.0/16        -> site1
  10.1.2.0/24        -> lab
  10.1.2.128/25      -> dmz

Lookup 10.1.2.200:  /0 /8 /16 /24 /25 all match -> /25, dmz
Lookup 10.1.2.77:   /0 /8 /16 /24 match         -> /24, lab
Lookup 10.1.9.9:    /0 /8 /16 match             -> /16, site1
Lookup 10.200.0.1:  /0 /8 match                 -> /8,  core
Lookup 8.8.8.8:     /0 only                     -> default, ISP-A

struct node {
    struct node *child[2];
    int has_route;
    int next_hop;
};

int lookup(const struct node *root, unsigned int dest) {
    const struct node *n = root;
    int best = -1;                  /* -1 means no route */
    for (int i = 31; i >= 0 && n; i--) {
        if (n->has_route)
            best = n->next_hop;     /* deeper match overrides */
        n = n->child[(dest >> i) & 1];
    }
    if (n && n->has_route)          /* a /32 ends on the last node */
        best = n->next_hop;
    return best;
}
